from batch07 import *
start('wireless','WLAN — radio, architektura i bezpieczeństwo','1.11',['https://www.cisco.com/c/en/us/td/docs/solutions/CVD/Campus/cisco-campus-lan-wlan-design-guide.html','https://www.cisco.com/c/en/us/td/docs/wireless/controller/8-10/config-guide/b_cg810/wlan_security.html','https://www.cisco.com/c/en/us/support/docs/wireless-mobility/80211/200527-Fundamentals-of-802-11-Wireless-Sniffing.html','https://www.cisco.com/c/en/us/td/docs/wireless/controller/8-5/config-guide/b_cg85/flexconnect.html'])
q('SSID a BSSID','Co identyfikuje SSID?','Nazwę logicznej sieci bezprzewodowej',['Zawsze jeden fizyczny port Ethernet|SSID nie identyfikuje portu przewodowego.','Maskę podsieci klienta|Maska należy do konfiguracji IP.','Numer kanału radiowego|Jedno SSID może działać na różnych kanałach.'],'SSID opisuje sieć WLAN; wiele BSS może ogłaszać tę samą nazwę.')
q('Dwa poziomy sygnału','Który poziom odbieranego sygnału jest silniejszy: −52 dBm czy −75 dBm?','−52 dBm',['−75 dBm|Bardziej ujemna wartość oznacza mniejszą moc.','Są identyczne|Różnica wynosi 23 dB.','Nie da się porównać dBm|dBm jest bezwzględną miarą mocy względem 1 mW.'],'Mniej ujemny wynik w dBm oznacza silniejszy sygnał, ale nie gwarantuje dobrej jakości.')
q('Sygnał a szum','Sygnał wynosi −65 dBm, szum −90 dBm. Ile wynosi SNR?','25 dB',['−155 dB|Nie dodajemy obu ujemnych wartości.','155 dBm|SNR jest stosunkiem wyrażanym w dB.','−25 dBm|Należy odjąć poziom szumu od poziomu sygnału.'],'SNR w dB = −65 − (−90) = 25.')
q('Wspólny kanał','Dwa pobliskie AP pracują na tym samym kanale. Jaki zasób współdzielą z klientami?','Czas dostępu do medium radiowego',['Osobny pełny kanał na każdego klienta|Klienci współdzielą medium.','Wyłącznie adres bramy|Problem dotyczy radia niezależnie od adresu IP.','Jedną sesję TCP dla całego WLAN|TCP jest oddzielny od zasad dostępu radiowego.'],'Urządzenia muszą dzielić airtime; mocny sygnał nie eliminuje konkurencji o medium.')
q('Kanały 2,4 GHz','Który zestaw jest klasycznym planem niepokrywających się kanałów przy szerokości 20 MHz w 2,4 GHz?','1, 6, 11',['1, 2, 3|Sąsiednie kanały w tym zestawie nakładają się.','6, 7, 8|Ten zestaw również nakłada się.','1, 1, 1|To ponowne użycie jednego kanału, nie trzy oddzielne kanały.'],'1/6/11 to powszechny punkt wyjścia; projekt musi uwzględniać lokalne regulacje i pomiary.')
q('Ukryte SSID','Czy wyłączenie rozgłaszania nazwy SSID zastępuje uwierzytelnianie i szyfrowanie?','Nie',['Tak, nazwy nie da się wtedy ustalić|Nazwa może nadal występować w wymianie ramek.','Tak, włącza automatycznie WPA3|Ukrycie SSID nie zmienia metody zabezpieczeń.','Tak, blokuje wszystkie obce stacje|To nie jest kontrola tożsamości klienta.'],'Ukrywanie nazwy nie tworzy kryptograficznej ochrony WLAN.')
q('CAPWAP','Do czego służy CAPWAP w architekturze z kontrolerem?','Komunikacji między AP a kontrolerem',['Wymiany tras BGP między PE|To inne protokoły i role.','Rozwiązywania nazw DNS klienta|CAPWAP nie zastępuje DNS.','Zmiany maski IPv4 w ARP|ARP nie negocjuje maski podsieci.'],'CAPWAP wspiera zarządzanie AP i zależnie od modelu obsługę ruchu danych.')
q('Local switching','Co oznacza lokalne przełączanie ruchu klienta w FlexConnect?','Ruch danych może wyjść lokalnie z AP do VLAN-u w oddziale',['Każdy pakiet musi przejść przez centralny WLC|To opis centralnego przełączania danych.','AP nigdy nie komunikuje się z kontrolerem|Zarządzanie może nadal być centralne.','Każdy klient dostaje publiczne IP|Sposób przełączania nie narzuca publicznej adresacji.'],'Płaszczyzna sterowania i lokalna droga danych nie muszą przebiegać identycznie.')
q('AP i kontroler','Jaka korzyść wynika z centralnego zarządzania wieloma AP?','Spójniejsze wdrażanie polityk i ustawień WLAN',['Brak potrzeby planowania radiowego|Centralizacja nie usuwa zakłóceń ani potrzeb projektu.','Nieskończona przepustowość kanału|Medium radiowe nadal ma ograniczenia.','Brak potrzeby uwierzytelniania klientów|Kontroler nie znosi wymagań bezpieczeństwa.'],'Centralizacja ułatwia zarządzanie, lecz nie zastępuje poprawnego projektu RF i sieci przewodowej.')
q('WPA2-Enterprise','Który element typowo wspiera indywidualne uwierzytelnianie klientów WPA2-Enterprise?','802.1X/EAP i serwer RADIUS',['Jedno hasło PSK współdzielone przez wszystkich|To model Personal, nie indywidualna tożsamość Enterprise.','Wyłącznie filtrowanie docelowego IP|Nie jest metodą uwierzytelnienia WLAN.','Tylko nazwa VLAN|Nazwa VLAN nie uwierzytelnia klienta.'],'Enterprise pozwala wykorzystać indywidualne poświadczenia lub certyfikaty zależnie od EAP.')
q('WPA3-Personal','Jaki mechanizm jest charakterystyczny dla WPA3-Personal?','SAE',['WEP|WEP jest starszą, odmienną metodą.','Telnet|Telnet nie jest uwierzytelnianiem Wi-Fi.','PAP bez ochrony radiowej|To nie charakterystyczny mechanizm WPA3-Personal.'],'SAE jest elementem WPA3-Personal i poprawia odporność na pasywne ataki słownikowe offline.')
q('To samo SSID','Dwa AP mają tę samą nazwę SSID. Czy to wystarcza do potwierdzenia zgodnej polityki dostępu?','Nie, trzeba sprawdzić także zabezpieczenia i mapowanie sieci',['Tak, nazwa przenosi pełną konfigurację|SSID nie koduje wszystkich ustawień.','Tak, gwarantuje ten sam adres IP klientów|Przydział IP zależy od sieci i DHCP.','Nie, dwa AP nigdy nie mogą mieć wspólnego SSID|Wspólne SSID jest normalne w rozbudowanym WLAN.'],'Nazwę sieci ocenia się wraz z uwierzytelnianiem, VLAN-em i architekturą roamingu.')
q('Silny sygnał, niska jakość','Klient ma RSSI −50 dBm, ale SNR 8 dB. Co to sugeruje?','Wysoki poziom szumu względem odbieranego sygnału',['Na pewno uszkodzony DNS|SNR opisuje radio, nie rozwiązywanie nazw.','Brak jakiegokolwiek sygnału|RSSI wskazuje wykryty sygnał.','Zawsze idealne warunki radiowe|Silny sygnał przy silnym szumie nie oznacza wysokiej jakości.'],'Oceniaj RSSI i SNR razem; sam poziom sygnału może być mylący.')
q('Za szeroki kanał','W gęstym WLAN zwiększono szerokość kanałów, ograniczając ich liczbę. Jakie ryzyko wzrasta?','Konkurencja między komórkami korzystającymi z tego samego widma',['Automatyczne wyłączenie WPA2|Szerokość nie wyłącza automatycznie zabezpieczeń.','Zamiana VLAN w VRF|To odrębna konfiguracja sieci.','Utrata możliwości użycia DHCP|Szerokość kanału nie zabrania DHCP.'],'Szerszy kanał może zwiększać szybkość pojedynczego połączenia, ale utrudnia ponowne wykorzystanie widma.')
q('Oddział bez WAN','FlexConnect utracił kontroler. Czy każdy nowy klient z dowolną metodą uwierzytelniania na pewno połączy się lokalnie?','Nie, zależy to od lokalnego przełączania, uwierzytelniania i dostępnych usług',['Tak, zawsze i niezależnie od konfiguracji|Tryb standalone ma warunki i ograniczenia.','Nie, AP zawsze wyłącza radio|To nie ogólna reguła FlexConnect.','Tak, bo DHCP zastępuje RADIUS|DHCP nie wykonuje uwierzytelniania 802.1X.'],'Dostępność danych lokalnych i możliwość uwierzytelnienia nowych klientów należy weryfikować osobno.')
q('WLAN działa, IP brak','Klient poprawnie uwierzytelnił się, ale nie otrzymuje adresu. Co jest rozsądnym następnym sprawdzeniem?','VLAN klienta i droga do DHCP',['Ponowna zmiana SSID na losową nazwę|Nie diagnozuje przydziału IP.','Natychmiastowe wyłączenie szyfrowania|Uwierzytelnienie już zakończyło się poprawnie.','Zwiększenie priorytetu HSRP bez sprawdzeń|To nie wskazana przyczyna braku DHCP.'],'Po warstwie radiowej i uwierzytelnieniu sprawdza się przypisanie do sieci i usługi IP.')
q('Portal a szyfrowanie','Czy sam portal logowania w otwartym WLAN oznacza, że wszystkie ramki radiowe są szyfrowane?','Nie',['Tak, HTML portalu szyfruje radio|Portal internetowy i szyfrowanie warstwy radiowej to inne mechanizmy.','Tak, jeśli portal ma logo firmy|Wygląd portalu nie zapewnia kryptografii.','Tak, DHCP włącza AES|DHCP nie negocjuje szyfrowania Wi-Fi.'],'HTTPS chroni daną sesję aplikacji, ale sam portal nie zapewnia szyfrowania całego WLAN.')
q('Decyzja o roamingu','Kto zwykle podejmuje decyzję o przejściu klienta do innego AP, przy możliwym wsparciu sieci?','Klient bezprzewodowy',['Wyłącznie serwer DNS|DNS nie wybiera AP klienta.','Zawsze tylko DHCP|DHCP nie wykonuje decyzji radiowej.','Przełącznik STP jako root|Root STP nie jest kontrolerem roamingu klienta.'],'Sieć może wspomagać lub wpływać na wybór, ale zachowanie klienta jest istotną częścią roamingu.')
end()
start('qos','QoS — klasyfikacja i kolejki','4.7',['https://www.cisco.com/c/en/us/support/docs/quality-of-service-qos/qos-packet-marking/10103-dscpvalues.html','https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/qos/b-quality-of-service/m_qos-mrkg.html','https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/qos_dfsrv/configuration/15-mt/qos-dfsrv-15-mt-book/qos-dfsrv.html','https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/qos_plcshp/configuration/xe-16/qos-plcshp-xe-16-book.pdf'])
q('Po co QoS?','Co QoS pozwala kontrolować w warunkach przeciążenia?','Sposób traktowania klas ruchu przy ograniczonych zasobach',['Fizyczne zwiększenie portu 100 Mb/s do 1 Gb/s|QoS nie zmienia możliwości sprzętowych portu.','Automatyczne szyfrowanie całego ruchu|QoS nie zastępuje szyfrowania.','Eliminację każdego rodzaju opóźnienia|Nie znosi ograniczeń propagacji i transmisji.'],'QoS zarządza ograniczonymi zasobami zamiast tworzyć dodatkowe pasmo.')
q('Klasyfikacja','Która czynność jest klasyfikacją ruchu?','Przypisanie pakietu do klasy na podstawie kryteriów',['Zapis nowej wartości DSCP|To oznaczanie, czyli marking.','Opóźnienie wysyłki w buforze|To może być element shaping lub kolejkowania.','Zmiana adresu źródłowego NAT|To translacja adresów.'],'Klasyfikacja rozpoznaje ruch, a kolejne działania określają jego obsługę.')
q('Marking','Co jest przykładem marking?','Ustawienie DSCP na EF',['Utworzenie sąsiedztwa OSPF|To operacja protokołu routingu.','Sprawdzenie MAC przez ARP|To rozwiązywanie adresu warstwy drugiej.','Wybór portu root STP|To działanie topologii L2.'],'Marking zapisuje oznaczenie, które inne urządzenia mogą wykorzystać zgodnie z polityką.')
q('Pole DSCP','Ile bitów ma DSCP?','6',['3|Trzy bity ma PCP/CoS w znaczniku 802.1Q.','8|Całe pole DS obejmuje także ECN.','16|To nie długość DSCP.'],'DSCP zajmuje sześć bitów, co daje 64 możliwe wartości.')
q('CoS w 802.1Q','Ile poziomów można zakodować w trzybitowym PCP/CoS?','8',['3|Liczba bitów nie jest liczbą kombinacji.','6|To liczba bitów DSCP.','64|Tyle kombinacji daje sześć bitów.'],'Trzy bity zapewniają 2^3 = 8 wartości.')
q('Jitter','Który opis najlepiej definiuje jitter?','Zmienność opóźnienia kolejnych pakietów',['Suma wszystkich bajtów w interfejsie|To objętość ruchu, nie jitter.','Adres serwera DNS|Nie opisuje czasu transmisji.','Wyłącznie stałe opóźnienie propagacji|Jitter dotyczy zmienności.'],'Aplikacje czasu rzeczywistego są wrażliwe zarówno na opóźnienie, jak i jego zmienność.')
q('Shaping','Co zwykle robi shaper z krótkim nadmiarem ruchu, jeśli ma wolny bufor?','Opóźnia wysyłkę, dostosowując tempo',['Zawsze natychmiast odrzuca każdy nadmiar|To nie podstawowa różnica shapingu wobec policingu.','Nadaje dane szybciej niż fizyczny port|Nie może przekroczyć możliwości łącza.','Zmienia każdemu pakietowi MAC na broadcast|Nie jest funkcją shapingu.'],'Shaping wygładza ruch przez buforowanie, kosztem opóźnienia i skończonej pojemności bufora.')
q('Policing','Która reakcja jest typowa dla policera na ruch ponad profil?','Odrzucenie lub zmiana oznaczenia według polityki',['Zawsze nieograniczone buforowanie|Policer nie jest nieograniczonym shaperem.','Automatyczna zmiana maski IP|Policing nie zmienia podsieci.','Dodanie drugiego fizycznego łącza|To nie działanie policera.'],'Akcje policera zależą od konfiguracji; exceed nie musi zawsze oznaczać drop.')
q('EF liczbowo','Jaką dziesiętną wartość DSCP ma EF?','46',['5|To nie wartość DSCP EF.','0|Zero odpowiada typowemu best effort.','63|Największa liczba nie oznacza EF.'],'EF ma kod 101110, czyli 46.')
q('AF drop precedence','W tej samej klasie AF, który kod ma wyższy drop precedence: AF31 czy AF33?','AF33',['AF31|Druga cyfra 1 oznacza niższą preferencję odrzucenia niż 3.','Zawsze są identyczne|Kody różnią się właśnie drop precedence.','Nie są w tej samej klasie|Pierwsza cyfra 3 określa wspólną klasę.'],'AFxy rozdziela klasę x i poziom odrzucania y; znaczenie realizuje polityka urządzenia.')
q('Granica zaufania QoS','Dlaczego nie należy bezwarunkowo ufać DSCP od dowolnego klienta?','Klient może sam oznaczyć zwykły ruch jako priorytetowy',['DSCP jest zawsze szyfrowane|Pole nie jest automatycznie chronione kryptograficznie.','Klient nie może ustawić nagłówka IP|Wiele stosów i aplikacji może ustawiać oznaczenia.','Oznaczenie zawsze zmienia trasę BGP|QoS i wybór tras nie są tym samym.'],'Na granicy zaufania weryfikuje się lub ponownie oznacza ruch zgodnie z polityką.')
q('Kolejka priorytetowa','Dlaczego kolejkę priorytetową trzeba projektować z ograniczeniami?','Nieograniczony priorytet może zagłodzić inne klasy',['Ponieważ priorytet zawsze szyfruje dane|Nie dotyczy szyfrowania.','Ponieważ wszystkie pakiety mają ten sam rozmiar|Rozmiary pakietów są różne.','Ponieważ DHCP zakazuje priorytetu|DHCP nie wprowadza takiego zakazu.'],'Priorytet dla czasu rzeczywistego powinien współistnieć z zasobami dla pozostałych usług.')
q('10 Mb/s pod ruchem 14 Mb/s','Na wyjście 10 Mb/s stale napływa 14 Mb/s. Czy skończony bufor shapera zapobiegnie utracie danych bez końca?','Nie, długotrwały nadmiar w końcu wyczerpie bufor',['Tak, bufor tworzy dodatkowe pasmo|Bufor przechowuje dane, nie zwiększa szybkości wyjścia.','Tak, jeśli DSCP wynosi 46|Oznaczenie nie usuwa ograniczeń pojemności.','Tak, 14 jest zawsze mniejsze od 10|Podane wartości przeczą temu założeniu.'],'Krótkie bursty można wygładzać, ale stały nadmiar wymaga ograniczenia ruchu lub większej przepustowości.')
q('Samo oznaczenie EF','Pakiety mają EF, ale sieć nie stosuje do niego żadnej specjalnej polityki. Czy oznaczenie gwarantuje małe opóźnienie?','Nie',['Tak, EF rezerwuje pasmo w całym Internecie|DSCP nie jest globalnym protokołem rezerwacji.','Tak, EF omija każde fizyczne łącze|Pakiety nadal podlegają ograniczeniom transmisji.','Tak, wartość 46 wyłącza kolejki|Kolejkowanie nie znika od samego kodu.'],'Oznaczenie jest informacją dla polityki; zachowanie musi zostać wdrożone na właściwych węzłach.')
q('Zła klasyfikacja głosu','Klasa VOICE ma zerowe liczniki podczas rozmowy. Co sprawdzić przed zwiększaniem jej pasma?','Czy kryteria klasy faktycznie dopasowują pakiety rozmowy',['Tylko czas dzierżawy DHCP|To nie wyjaśnia zerowych liczników klasy.','Wyłącznie kolor ikony telefonu|Nie weryfikuje dopasowania pakietów.','Od razu usunąć wszystkie klasy|To zmiana bez diagnozy przyczyny.'],'Brak dopasowania oznacza, że zmiana zasobów tej klasy może nie wpłynąć na badany ruch.')
q('Utrata a jitter','Po zmianie kolejki maleją dropy, lecz rośnie opóźnienie. Jaki mechanizm może to wyjaśnić?','Dłuższe przetrzymywanie pakietów w buforze',['Mniejsza liczba bajtów w nagłówku IPv4|Nie jest wskazanym skutkiem zmiany kolejki.','Automatyczne przejście z TCP na UDP|Kolejka nie zmienia protokołu transportowego.','Zmiana MAC na router ID|Te identyfikatory nie są zamienne.'],'Większy bufor może zmniejszyć krótkotrwałe straty kosztem opóźnienia; należy mierzyć oba parametry.')
q('CoS bez tagu','Czy zwykła nieotagowana ramka Ethernet zawiera pole PCP znacznika 802.1Q?','Nie',['Tak, PCP jest częścią każdego adresu MAC|PCP należy do tagu 802.1Q.','Tak, jest w FCS|FCS jest sumą kontrolną ramki.','Tak, zawsze w polu EtherType|EtherType nie jest polem PCP.'],'Brak tagu oznacza brak jego pola PCP; klasyfikacja może używać innych informacji, np. DSCP.')
q('QoS end-to-end','Jak ocenić politykę dla rozmów między dwoma oddziałami?','Sprawdzić klasyfikację, oznaczenia i obsługę na kolejnych wąskich gardłach',['Tylko odczytać DSCP na pierwszym hoście|Dalsze węzły mogą traktować ruch inaczej.','Sprawdzić wyłącznie nazwę policy-map|Nazwa nie dowodzi działania.','Założyć, że jeden router gwarantuje cały szlak|QoS w jednym miejscu nie kontroluje wszystkich odcinków.'],'Wynik dla aplikacji zależy od całej ścieżki oraz faktycznie przeciążonych zasobów.')
end()
